    db.select({ id: kitchenTickets.id }).from(kitchenTickets).where(or(eq2(kitchenTickets.approvedByOperatorId, id), eq2(kitchenTickets.deliveredByOperatorId, id))).limit(1),
    db.select({ id: ticketStockHistory.id }).from(ticketStockHistory).where(eq2(ticketStockHistory.changedByOperatorId, id)).limit(1)
