async function buildPnlWarnings(params) {
  const db = await getDb();
  const warnings = [];
  const merchandiseExpenses = params.directRows.filter((e) => e.category === "barra" || e.category === "merch");
  if (params.cogs > 0 && merchandiseExpenses.length > 0) {
    warnings.push(
      `Hay ${merchandiseExpenses.length} gasto(s) de barra/merch y adem\xE1s costo de producto cargado en la carta. Si es la misma mercader\xEDa la est\xE1s contando dos veces: marc\xE1 esos gastos como "ya contado en el costo del producto".`
    );
  }
  if (db) {
    const refunded = await db.select({ id: orders.id }).from(orders).where(and(eq2(orders.eventId, params.eventId), eq2(orders.paymentStatus, "refunded")));
    if (refunded.length > 0) {
      const refundedIds = refunded.map((r) => r.id);
      const withCommission = await db.select({ id: ambassadorCommissions.id }).from(ambassadorCommissions).where(inArray(ambassadorCommissions.orderId, refundedIds));
      if (withCommission.length > 0) {
        warnings.push(
          `Hay ${withCommission.length} comisi\xF3n(es) de embajador sobre \xF3rdenes reembolsadas. El sistema no las revierte solo: revisalas a mano.`
        );
      }
    }
    if (params.grossIncome > 0) {
      const commissionExpenses = await db.select({ id: expenses.id }).from(expenses).where(and(eq2(expenses.periodMonth, params.monthKey), eq2(expenses.category, "comisiones")));
      if (commissionExpenses.length === 0) {
        warnings.push(
          `No hay ning\xFAn gasto de categor\xEDa "Comisiones" en ${params.monthKey}. Las comisiones de Mercado Pago (~3,5%) no se calculan solas: cargalas desde la liquidaci\xF3n o la utilidad queda inflada.`
        );
      }
    }
  }
  return warnings;
}
