      [
        { key: "expenseDate", label: "Fecha" },
        { key: "category", label: "Categor\xEDa" },
        { key: "description", label: "Descripci\xF3n" },
        { key: "supplier", label: "Proveedor" },
        { key: "amountTotal", label: "Monto" },
        { key: "paymentMethod", label: "Medio de pago" }
      ]
