// server/_core/context.ts
init_const();
import { parse as parseCookieHeader3 } from "cookie";
async function createContext(opts) {
  let user = null;
  try {
    user = await sdk.authenticateRequest(opts.req);
  } catch (error) {
    user = null;
  }
  const cookies = parseCookieHeader3(opts.req.headers.cookie ?? "");
  const sessionPayload = await verifyOperatorSession(cookies[CAJA_COOKIE_NAME]);
  let operator = null;
  if (sessionPayload) {
    const dbOperator = await getOperatorById(sessionPayload.operatorId);
    if (dbOperator && dbOperator.active) {
      operator = { operatorId: dbOperator.id, role: dbOperator.role, name: dbOperator.name, eventId: dbOperator.eventId };
    }
  }
  const deviceSessionPayload = await verifyDeviceSession(cookies[CAJA_DEVICE_COOKIE_NAME]);
  let device = null;
  if (deviceSessionPayload) {
    const dbDevice = await getDeviceById(deviceSessionPayload.deviceId);
    if (dbDevice && dbDevice.enrolled && dbDevice.active) {
      device = { deviceId: dbDevice.id, name: dbDevice.name, eventId: dbDevice.eventId };
    }
  }
  return {
    req: opts.req,
    res: opts.res,
    user,
    operator,
    device
  };
}

// server/_core/seoRoutes.ts
init_content();
var ORIGIN = (process.env.CANONICAL_ORIGIN || "https://mansionplayroom.cl").replace(/\/$/, "");
function xmlEscape(value) {
  return value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}
function absolute(path2) {
  return `${ORIGIN}${path2}`;
}
function getRobotsText() {
  return [
    "User-agent: *",
    "Allow: /",
    "Disallow: /admin",
    "Disallow: /caja",
    "Disallow: /puerta",
    "Disallow: /cocina",
    "Disallow: /guardarropia",
    "Disallow: /gastos",
    "Disallow: /fiesta",
    "Disallow: /checkout",
    "Disallow: /pago",
    "Disallow: /verificar",
    "Disallow: /api/",
    "",
    `Sitemap: ${absolute("/sitemap.xml")}`,
    ""
  ].join("\n");
}
function buildSitemap(paths) {
  const unique = Array.from(new Set(paths));
  const entries = unique.map((path2) => `  <url><loc>${xmlEscape(absolute(path2))}</loc></url>`).join("\n");
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${entries}
</urlset>
`;
}
async function getSitemapXml() {
  let eventPaths = [];
  try {
    const events2 = await getPublishedEvents();
    eventPaths = events2.map((event) => `/eventos/${event.slug}`);
  } catch (error) {
    console.error("[SEO] sitemap event lookup failed:", error);
  }
  const staticPaths = [
    "/",
    "/eventos",
    "/entradas",
    "/nosotros",
    "/embajadores",
    "/panoramas",
    "/blog",
    "/politica-de-reembolso",
    "/politica-de-privacidad",
    ...ALL_ARTICLES.map(articlePath)
  ];
  return buildSitemap([...staticPaths, ...eventPaths]);
}
function registerSeoRoutes(app2) {
  app2.get("/robots.txt", (_req, res) => {
    res.type("text/plain").send(getRobotsText());
  });
  app2.get("/sitemap.xml", async (_req, res) => {
    res.type("application/xml").send(await getSitemapXml());
  });
}

// server/_core/app.ts
function createApp() {
  const app2 = express();
  app2.use(express.json({ limit: "10mb" }));
  app2.use(express.urlencoded({ limit: "10mb", extended: true }));
  registerOAuthRoutes(app2);
  registerAdminRoutes(app2);
  registerCronRoutes(app2);
  registerTicketAssetRoutes(app2);
  registerSeoRoutes(app2);
  app2.use(webhooksRouter);
  app2.use(
    "/api/trpc",
    createExpressMiddleware({
      router: appRouter,
      createContext
    })
  );
  return app2;
}

